# name: within_set_target_spread
# description: Mean over sets with >=4 distinct targets (each with >=5 responses) of the standard deviation of per-target yes-rates within the set; observed > null means people discriminate among targets of the same set more sharply than the model predicts (model's target-level gradients too flat), observed < null the reverse.
def test_statistic(df):
    g = df.groupby(["number_set", "target"])["rating"].agg(["mean", "count"]).reset_index()
    g = g[g["count"] >= 5]
    s = g.groupby("number_set")["mean"].agg(["std", "count"])
    s = s[s["count"] >= 4]
    if len(s) == 0:
        return 0.0
    return float(s["std"].mean())

# name: prime_set_prime_target_boost
# description: In multi-example sets whose examples are all primes, yes-rate on prime targets minus yes-rate on odd non-prime targets (targets equal to an example excluded); observed > null means the model under-produces a "prime numbers" concept, observed < null means it over-generalises to odd composites.
def test_statistic(df):
    P = {p for p in range(2, 101) if all(p % k for k in range(2, int(p ** 0.5) + 1))}
    sets = df["number_set"].astype(str)
    cats = pd.unique(sets)
    info = {}
    for s in cats:
        xs = [int(x) for x in s.split(",")]
        info[s] = (len(xs) >= 2 and all(x in P for x in xs), set(xs))
    ok = sets.map(lambda s: info[s][0]).values.astype(bool)
    t = df["target"].astype(int).values
    is_ex = np.array([ti in info[s][1] for s, ti in zip(sets.values, t)])
    isp = np.isin(t, list(P))
    r = df["rating"].values.astype(float)
    a = ok & ~is_ex & isp
    b = ok & ~is_ex & ~isp & (t % 2 == 1)
    if a.sum() == 0 or b.sum() == 0:
        return 0.0
    return float(r[a].mean() - r[b].mean())

# name: cross_position_digit_overlap
# description: Among targets matching no example's final digit and whose decade lies outside the examples' decade range, yes-rate when a target digit appears in an example in the other position (target tens = an example's units, or target units = an example's tens) minus yes-rate otherwise; observed > null means people credit position-free digit identity (e.g. 31 vs 13) that the model, using only final digits and decade bands, misses.
def test_statistic(df):
    sets = df["number_set"].astype(str)
    cats = pd.unique(sets)
    info = {}
    for s in cats:
        xs = [int(x) for x in s.split(",")]
        units = {x % 10 for x in xs}
        tens = {(x // 10) % 10 for x in xs if x >= 10}
        info[s] = (units, tens, min(x // 10 for x in xs), max(x // 10 for x in xs))
    sv = sets.values
    t = df["target"].astype(int).values
    tu = t % 10
    tt = (t // 10) % 10
    elig = np.zeros(len(t), bool)
    cross = np.zeros(len(t), bool)
    for i, (s, ti) in enumerate(zip(sv, t)):
        units, tens, lo, hi = info[s]
        td = ti // 10
        if (tu[i] in units) or (lo <= td <= hi):
            continue
        elig[i] = True
        cross[i] = (ti >= 10 and tt[i] in units) or (tu[i] in tens)
    r = df["rating"].values.astype(float)
    a = elig & cross
    b = elig & ~cross
    if a.sum() == 0 or b.sum() == 0:
        return 0.0
    return float(r[a].mean() - r[b].mean())

# name: unstructured_set_breadth
# description: Yes-rate on targets sharing no final digit with any example in "unstructured" sets (>=3 examples, gcd 1, mixed parity, >=3 distinct final digits) minus the same rate in singleton sets; observed > null means people generalise more broadly from diverse, rule-less examples ("any number") than the model predicts, observed < null that they generalise less.
def test_statistic(df):
    sets = df["number_set"].astype(str)
    cats = pd.unique(sets)
    info = {}
    for s in cats:
        xs = [int(x) for x in s.split(",")]
        g = 0
        for x in xs:
            g = math.gcd(g, x)
        par = {x % 2 for x in xs}
        units = {x % 10 for x in xs}
        kind = 1 if len(xs) == 1 else (2 if (len(xs) >= 3 and g == 1 and len(par) == 2 and len(units) >= 3) else 0)
        info[s] = (kind, units)
    sv = sets.values
    t = df["target"].astype(int).values
    kind = np.array([info[s][0] for s in sv])
    dm = np.array([(ti % 10) in info[s][1] for s, ti in zip(sv, t)])
    r = df["rating"].values.astype(float)
    a = (kind == 2) & ~dm
    b = (kind == 1) & ~dm
    if a.sum() == 0 or b.sum() == 0:
        return 0.0
    return float(r[a].mean() - r[b].mean())
